    elif conclusion == 'failed':
        model_stats[model_size]['failed'] += 1
    elif conclusion == 'killed':
        model_stats[model_size]['killed'] += 1
    elif conclusion == 'negative':
        model_stats[model_size]['negative'] += 1
    else:
